                entry.url = url;
            }
            return { success: true };
        } catch (err) {
            console.error('[XScraper] Firefox navigate error:', err);
            return { success: false, error: err.message };
        }
    });
    // Scrape current page
    ipcMain.handle('xscraper:scrape-current', async () => {
        try {
            // Find the active Firefox window
            let activeWindow = null;
            for (const entry of firefoxWindows.values()) {
                if (!entry.window.isDestroyed()) {
                    activeWindow = entry;
                    break;
                }
            }
            if (!activeWindow) {
                return { success: false, error: 'No active Firefox window found' };
            }
            // Execute scraping in the page context
            const result = await activeWindow.window.webContents.executeJavaScript(                (function() {                     if (window.__grokScraper && typeof window.__grokScraper.scrapeAll === 'function') {                         return window.__grokScraper.scrapeAll();                     }                     return { success: false, error: 'Scraper not available' };                 })()            );
            return result;
        } catch (err) {
            console.error('[XScraper] Scrape error:', err);
            return { success: false, error: err.message };
        }
    });
    // Export data
    ipcMain.handle('xscraper:export-data', async () => {
        try {
            // Find the active Firefox window
            let activeWindow = null;
